ee:message.ee:set-payload:
%dw 2.0
output application/json

var billingData= vars.billingResponsePayload 

//formatting, to get numbers properly formatted to #.## takes a bit of mumbo jumbo
// as Number as String {format:"0.00"} as Number

//to check typeOf transaction
fun checkTransactionType(transactionsData)=(
    if ((typeOf(transactionsData)) contains "Object")
    	//wrap in [] to make it an array
    	mapTransactions([transactionsData])
    else if ((typeOf(transactionsData)) contains "Array")
    	mapTransactions(transactionsData)
    else
    	[]
)

//the response from Billing has a lot of fields on each transaction. Only map the ones we want.
fun mapTransactions(transactions) = (
    transactions map (
        {
            "amountDue": $.amountDue as Number as String {format: "0.00"} as Number default null,
            "description":$.description,
            "dueDate": $.dueDate,
            "processingDate": $.processingDate
        }
    )
)
---
checkTransactionType(billingData.primaryAccount.transactions)
